"""Capture exact tested V16 candidate; no publication and no native-acceptance claim."""
from pathlib import Path
import hashlib,json,datetime,subprocess
R=Path(__file__).resolve().parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
subprocess.run(['node','tests/v16-scope.test.mjs'],cwd=R/'web',check=True)
paths=[R/'web/index.html']+[p for d in ['web/src','web/public'] for p in (R/d).rglob('*') if p.is_file()]
rows=[{'path':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':H(p)} for p in sorted(paths)]
gate=json.loads((R/'tests/v16/final_gate_receipt.json').read_text());assert gate['result']=='PASS' and gate['runtime_unchanged_during_gate'] is True
assert {x['path']:x['sha256'] for x in rows}==gate['runtime_hashes'],'Runtime differs from tested snapshot'
tree=hashlib.sha256(''.join(x['path']+'\0'+x['sha256']+'\n' for x in sorted(rows,key=lambda x:x['path'])).encode()).hexdigest()
anchors=['dist/malabar-hot-coast.html','dist/game.bundle.js','dist/ui-preview.html','dist/v16-ui-preview.html','web/package.json','web/package-lock.json','web/build-standalone.mjs','web/build-ui-preview.mjs','tests/v16/full_gate.log','tests/v16/final_gate_receipt.json','tests/v16/surface_scene_metrics.json','tests/recovery/standalone_integrity.json','assets/surface_test/manifest.json','assets/surface_test/glb_validation.json','assets/surface_test/native_validation.json','docs/v16/model_contract.md','docs/v16/BROWSER_ACCEPTANCE_PLAN.md']
report={'candidate':'MALABAR V16 optional solo wall-run contact proof','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'base':'V15 Sites32 commit eef5ff3d5a462d817639fbd1d325578e89841a88','runtime_tree_sha256':tree,'tree_algorithm':'SHA256 of sorted relative-path + NUL + file SHA256 + newline','runtime_files':rows,'anchors':{n:{'bytes':(R/n).stat().st_size,'sha256':H(R/n)} for n in anchors},'status':'Source/model/actual-GLB/scene-graph/build checks passed; native GPU/human/audio acceptance pending separately.','protected':'127 V15 runtime files remain byte-identical, including normal gameplay, save/economy/story/audio/style and pre-existing assets. Reverse traction fix retained.','scope':['Explicit opt-in solo 900m flat-to-90-degree-wall-to-flat original Blender route','Fixed-120Hz true surface-frame support, finite arcade adhesion, gravity release/recontact and safe return','Local-frame car and camera, existing owned-car/read-only-tune support, no coins/rewards/AI/boost/flight in proof','Help version correction and natural V15 ramp directions; normal route catalogue remains unchanged'],'limits':['No ceiling/tube/full-loop or generalized rigid-body simulation','Safety return on static support contact, not a rigid-body crash impulse; outer rails non-solid guidance','Bounded wheel-plane approximation on twisting ribbon, not independent suspension','Camera local clearance is not universal scenery occlusion avoidance','No native GPU/FPS/audio/touch acceptance inferred from source/Blender tests','Sparse engineering test corridor, not photoreal scenery or a finished racing district'],'license':'Required OSM/Three/font notices and approved neutral original-material wording retained; no new reuse grant or historical-revocation claim; private reference media excluded.'}
(R/'tests/release/V16_RELEASE.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'runtime_files':len(rows),'runtime_tree_sha256':tree,'standalone':report['anchors']['dist/malabar-hot-coast.html']},indent=2))
